-- RevOps demo data, dropped and reloaded by the revops-seed service on every `docker compose up`.
-- CSVs are generated by dev-environment/data/seeds/revops/generate.py.
-- COPY reads them from the postgres container's /data/seeds mount.

DROP SCHEMA IF EXISTS revops CASCADE;
CREATE SCHEMA revops;

CREATE TABLE revops.accounts (
    account_id           TEXT PRIMARY KEY,
    account_name         TEXT,
    region               TEXT,
    sub_region           TEXT,
    segment              TEXT,
    account_owner        TEXT,
    solutions_engineer   TEXT,
    funnel_stage_number  INTEGER,
    funnel_stage         TEXT,
    tam_category         TEXT,
    behavior_signal      TEXT,
    sales_activity_pulse TEXT
);
COPY revops.accounts FROM '/data/seeds/revops/accounts.csv' WITH (FORMAT csv, HEADER MATCH);

CREATE TABLE revops.opportunities (
    opp_id         TEXT PRIMARY KEY,
    account_id     TEXT REFERENCES revops.accounts (account_id),
    opp_type       TEXT,
    stage_number   INTEGER,
    stage_name     TEXT,
    close_date     DATE,
    fiscal_quarter TEXT,
    net_nacv       NUMERIC
);
COPY revops.opportunities FROM '/data/seeds/revops/opportunities.csv' WITH (FORMAT csv, HEADER MATCH);
